SELECT t.id || ' — родитель не назван полем' AS detail FROM project_plan_tasks t WHERE t.project_id = $1 AND t.kind = 'red' AND t.parent_task_id = '' UNION ALL SELECT t.id || ' — перечень проверок пуст' FROM project_plan_tasks t WHERE t.project_id = $1 AND t.kind = 'red' AND NOT EXISTS (SELECT 1 FROM project_task_check c WHERE c.project_id = t.project_id AND c.task_id = t.id) UNION ALL SELECT t.id || ' — нет раздела «Признак готовности»' FROM project_plan_tasks t WHERE t.project_id = $1 AND t.kind = 'red' AND NOT EXISTS (SELECT 1 FROM project_document_sections s WHERE s.project_id = t.project_id AND s.entity_kind = t.entity_kind AND s.entity_name = t.entity_name AND s.title = 'Признак готовности') UNION ALL SELECT t.id || ' — родителя ' || t.parent_task_id || ' нет среди задач' FROM project_plan_tasks t WHERE t.project_id = $1 AND t.kind = 'red' AND t.parent_task_id <> '' AND NOT EXISTS (SELECT 1 FROM project_plan_tasks p WHERE p.project_id = t.project_id AND p.id = t.parent_task_id) ORDER BY 1
